package com.company.skillplatform.bundle.infrastructure.entity;
import com.company.skillplatform.artifact.infrastructure.entity.SkillArtifactEntity;import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import jakarta.persistence.*;
@Entity@Table(name="skill_bundle_item")public class SkillBundleItemEntity extends BaseJpaEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="bundle_id")private SkillBundleEntity bundle;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="skill_version_id")private SkillVersionEntity version;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="artifact_id")private SkillArtifactEntity artifact;@Column(name="root_selected",nullable=false)private boolean rootSelected;@Column(name="dependency_depth",nullable=false)private int dependencyDepth;@Column(name="required_by_path",nullable=false,length=2048)private String requiredByPath;protected SkillBundleItemEntity(){}public SkillBundleItemEntity(SkillBundleEntity b,SkillVersionEntity v,SkillArtifactEntity a,boolean root,int depth,String path){bundle=b;version=v;artifact=a;rootSelected=root;dependencyDepth=depth;requiredByPath=path;}public SkillVersionEntity getVersion(){return version;}public SkillArtifactEntity getArtifact(){return artifact;}public int getDependencyDepth(){return dependencyDepth;}}
